# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÇOKGENLERİN SINIFLANDIRILMASI: DIŞBÜKEY (KONVEKS) VE İÇBÜKEY (KONKAV)</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. Dışbükey (Konveks) Çokgen</text>\n  <polygon points="95,85 155,110 135,185 55,185 35,110" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="2.5"/>\n  <line x1="62" y1="125" x2="128" y2="155" stroke="#15803d" stroke-width="2.2"/>\n  <circle cx="62" cy="125" r="3.5" fill="#15803d"/>\n  <circle cx="128" cy="155" r="3.5" fill="#15803d"/>\n  <text x="72" y="120" font-size="10" font-weight="bold" fill="#15803d">K</text>\n  <text x="132" y="152" font-size="10" font-weight="bold" fill="#15803d">L</text>\n  <text x="95" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">Konveks Beşgen</text>\n  <text x="172" y="102" font-size="10" fill="#334155">• Her bir iç açısı <tspan font-weight="bold" fill="#1e40af">&lt; 180°</tspan>\'dir.</text>\n  <text x="172" y="126" font-size="10" fill="#334155">• İçteki [KL] doğru parçası</text>\n  <text x="180" y="141" font-size="10" fill="#334155">tamamen iç bölgededir.</text>\n  <text x="172" y="165" font-size="10" fill="#334155">• Bütün köşegenleri çokgenin</text>\n  <text x="180" y="180" font-size="10" fill="#334155">iç bölgesinde kesişir.</text>\n  <text x="172" y="204" font-size="10" font-weight="bold" fill="#15803d">• İç açı + Dış açı = 180°</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">2. İçbükey (Konkav) Çokgen</text>\n  <polygon points="435,85 505,105 460,142 500,190 385,180" fill="#fecaca" stroke="#b91c1c" stroke-width="2.5"/>\n  <line x1="505" y1="105" x2="500" y2="190" stroke="#dc2626" stroke-dasharray="4,3" stroke-width="2"/>\n  <circle cx="460" cy="142" r="4" fill="#991b1b"/>\n  <text x="430" y="146" font-size="9.5" font-weight="bold" fill="#991b1b">&gt;180°</text>\n  <text x="445" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#991b1b">Konkav Beşgen</text>\n  <text x="520" y="102" font-size="10" fill="#334155">• En az bir iç açısı <tspan font-weight="bold" fill="#991b1b">&gt; 180°</tspan>\'dir.</text>\n  <text x="520" y="126" font-size="10" fill="#334155">• Bazı iki noktayı birleştiren</text>\n  <text x="528" y="141" font-size="10" fill="#334155">parça dış bölgeye taşar.</text>\n  <text x="520" y="165" font-size="10" fill="#334155">• En az bir köşegeni (kesikli</text>\n  <text x="528" y="180" font-size="10" fill="#334155">çizgi) dış bölgeden geçer.</text>\n  <text x="520" y="204" font-size="10" font-weight="bold" fill="#991b1b">• Girintili köşesi bulunur.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">n KENARLI DIŞBÜKEY ÇOKGENDE ÜÇGENLEME VE KÖŞEGEN BAĞINTILARI</text>\n  <rect x="20" y="44" width="250" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="145" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Altıgende Üçgenleme (n = 6)</text>\n  <polygon points="105,82 185,82 220,138 185,194 105,194 70,138" fill="#fde68a" stroke="#b45309" stroke-width="2.2"/>\n  <line x1="105" y1="82" x2="220" y2="138" stroke="#dc2626" stroke-dasharray="4,3" stroke-width="2"/>\n  <line x1="105" y1="82" x2="185" y2="194" stroke="#dc2626" stroke-dasharray="4,3" stroke-width="2"/>\n  <line x1="105" y1="82" x2="105" y2="194" stroke="#dc2626" stroke-dasharray="4,3" stroke-width="2"/>\n  <circle cx="105" cy="82" r="4.5" fill="#dc2626"/>\n  <text x="93" y="79" font-size="11" font-weight="bold" fill="#dc2626">A</text>\n  <text x="88" y="145" font-size="10.5" font-weight="bold" fill="#78350f">1.</text>\n  <text x="128" y="162" font-size="10.5" font-weight="bold" fill="#78350f">2.</text>\n  <text x="165" y="148" font-size="10.5" font-weight="bold" fill="#78350f">3.</text>\n  <text x="180" y="110" font-size="10.5" font-weight="bold" fill="#78350f">4.</text>\n  <text x="145" y="216" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">A köşesinden: 6 - 3 = 3 köşegen</text>\n  <text x="145" y="230" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Oluşan üçgen: 6 - 2 = 4 üçgen</text>\n\n  <rect x="285" y="44" width="395" height="194" rx="10" fill="#ffffff" stroke="#2563eb" stroke-width="2"/>\n  <text x="482" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Dışbükey Çokgen Temel Bağıntıları Tablosu</text>\n\n  <rect x="298" y="76" width="368" height="34" rx="6" fill="#eff6ff" stroke="#93c5fd" stroke-width="1.2"/>\n  <text x="308" y="97" font-size="10.5" font-weight="bold" fill="#1e3a8a">1. Bir Köşeden Çizilen Köşegen Sayısı:</text>\n  <text x="654" y="97" text-anchor="end" font-size="12" font-weight="bold" fill="#dc2626">n - 3</text>\n\n  <rect x="298" y="116" width="368" height="34" rx="6" fill="#f0fdf4" stroke="#86efac" stroke-width="1.2"/>\n  <text x="308" y="137" font-size="10.5" font-weight="bold" fill="#14532d">2. Bir Köşeden Köşegenlerle Oluşan Üçgen Sayısı:</text>\n  <text x="654" y="137" text-anchor="end" font-size="12" font-weight="bold" fill="#15803d">n - 2</text>\n\n  <rect x="298" y="156" width="368" height="34" rx="6" fill="#fefce8" stroke="#fde047" stroke-width="1.2"/>\n  <text x="308" y="177" font-size="10.5" font-weight="bold" fill="#713f12">3. Çokgenin Toplam Köşegen Sayısı:</text>\n  <text x="654" y="177" text-anchor="end" font-size="12" font-weight="bold" fill="#b45309">n · (n - 3) / 2</text>\n\n  <rect x="298" y="196" width="368" height="34" rx="6" fill="#f3e8ff" stroke="#d8b4fe" stroke-width="1.2"/>\n  <text x="308" y="217" font-size="10.5" font-weight="bold" fill="#581c87">4. İç Açılar ve Dış Açılar Toplamı:</text>\n  <text x="654" y="217" text-anchor="end" font-size="11.5" font-weight="bold" fill="#6d28d9">İç: (n - 2)·180°  |  Dış: 360°</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DÜZGÜN ÇOKGENLERDE AÇI, KÖŞEGEN VE SİMETRİ EKSENİ ÖZELLİKLERİ</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Düzgün Beşgen (n = 5)</text>\n  <polygon points="125,78 168,108 152,158 98,158 82,108" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="2"/>\n  <line x1="125" y1="78" x2="152" y2="158" stroke="#dc2626" stroke-width="1.6"/>\n  <line x1="125" y1="78" x2="98" y2="158" stroke="#dc2626" stroke-width="1.6"/>\n  <text x="32" y="180" font-size="10" font-weight="bold" fill="#1e40af">• Dış Açı: 360°/5 = 72° | İç Açı: 108°</text>\n  <text x="32" y="198" font-size="10" fill="#334155">• 5 köşegenin tamamı birbirine eşittir.</text>\n  <text x="32" y="214" font-size="10" fill="#334155">• Köşegenler tepeyi 36°-36°-36° böler.</text>\n  <text x="32" y="230" font-size="10" fill="#334155">• 5 tane simetri ekseni vardır.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Düzgün Altıgen (n = 6)</text>\n  <polygon points="325,80 375,80 400,120 375,160 325,160 300,120" fill="#bbf7d0" stroke="#15803d" stroke-width="2"/>\n  <line x1="300" y1="120" x2="400" y2="120" stroke="#dc2626" stroke-width="1.8"/>\n  <line x1="325" y1="80" x2="325" y2="160" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="358" y="116" font-size="9.5" font-weight="bold" fill="#dc2626">2a</text>\n  <text x="303" y="138" font-size="9" font-weight="bold" fill="#1d4ed8">a·kök(3)</text>\n  <text x="257" y="180" font-size="10" font-weight="bold" fill="#15803d">• Dış Açı: 360°/6 = 60° | İç Açı: 120°</text>\n  <text x="257" y="198" font-size="10" fill="#334155">• Uzun köşegen = 2a (6 eşkenar üçgen)</text>\n  <text x="257" y="214" font-size="10" fill="#334155">• Kısa köşegen = a·kök(3) (30-30-120)</text>\n  <text x="257" y="230" font-size="10" fill="#334155">• 6 tane simetri ekseni vardır.</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. Simetri ve Hızlı Açı Tablosu</text>\n  <rect x="484" y="78" width="182" height="76" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="492" y="95" font-size="10" font-weight="bold" fill="#78350f">• Sekizgen (n=8): Dış 45° | İç 135°</text>\n  <text x="492" y="112" font-size="10" font-weight="bold" fill="#78350f">• Dokuzgen (n=9): Dış 40° | İç 140°</text>\n  <text x="492" y="129" font-size="10" font-weight="bold" fill="#78350f">• Ongen (n=10): Dış 36° | İç 144°</text>\n  <text x="492" y="146" font-size="10" font-weight="bold" fill="#78350f">• Onikigen (n=12): Dış 30° | İç 150°</text>\n  <text x="482" y="174" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#92400e">n tek ise:</tspan> Simetri eksenleri bir</text>\n  <text x="490" y="188" font-size="9.5" fill="#334155">köşeden ve karşı kenar ortasından geçer.</text>\n  <text x="482" y="206" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#92400e">n çift ise:</tspan> Yarısı karşılıklı köşelerden,</text>\n  <text x="490" y="220" font-size="9.5" fill="#334155">yarısı kenar ortalarından geçer.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
